package com.tanmay.corebanking.service;
import com.tanmay.corebanking.exception.AuthenticationException; import com.tanmay.corebanking.model.User; import com.tanmay.corebanking.util.*; import java.util.concurrent.*;
public class PinChangeService {private static final long OTP_VALIDITY=120_000L;private final AuthenticationService auth;private final ConcurrentHashMap<String,Otp> otps=new ConcurrentHashMap<>();private record Otp(String code,long expiresAt){}
 public PinChangeService(AuthenticationService a){auth=a;} public String generateOTP(User u){String code=OTPGenerator.generateOTP();otps.put(u.getUserId(),new Otp(code,System.currentTimeMillis()+OTP_VALIDITY));EmailUtil.sendEmail(u.getEmail(),"Core Banking - PIN Change OTP","Your OTP for PIN change is: "+code+"\n\nThis OTP is valid for 120 seconds.\nIf you did not request this, ignore this email.");return code;}
 public void changePin(User u,String current,String otp,String newPin){auth.verifyCurrentPin(u,current);if(!PinValidator.isValid(newPin))throw new AuthenticationException("New PIN must contain exactly 4 digits.");Otp x=otps.get(u.getUserId());if(x==null||System.currentTimeMillis()>x.expiresAt()){otps.remove(u.getUserId());throw new AuthenticationException("OTP is invalid or expired.");}if(!x.code().equals(otp))throw new AuthenticationException("Invalid OTP.");if(PinUtil.verifyPin(newPin,u.getPinHash()))throw new AuthenticationException("New PIN must be different from current PIN.");u.changePin(PinUtil.hashPin(newPin));otps.remove(u.getUserId());}
}
